  const bx = P3[0] - P1[0], by = P3[1] - P1[1];
  if (ax * bx + ay * by <= 0) return 'N';

  // 2) |P1P2| == |P1P3|
  if (ax * ax + ay * ay !== bx * bx + by * by) return 'N';

  // 3) P2,P3,P4,P5 colineares
