  if (P2[0] + P3[0] !== P4[0] + P5[0] || P2[1] + P3[1] !== P4[1] + P5[1]) return 'N';

  // 5) |P2P3| > |P4P5|
  const fx = P5[0] - P4[0], fy = P5[1] - P4[1];
  if (dx23 * dx23 + dy23 * dy23 <= fx * fx + fy * fy) return 'N';

  // 6) P4P6 e P5P7 perpendiculares a P2P3
  const gx = P6[0] - P4[0], gy = P6[1] - P4[1];
  const hx = P7[0] - P5[0], hy = P7[1] - P5[1];
  if (gx * dx23 + gy * dy23 !== 0) return 'N';
  if (hx * dx23 + hy * dy23 !== 0) return 'N';

  // 7) |P4P6| == |P5P7|
  if (gx * gx + gy * gy !== hx * hx + hy * hy) return 'N';

  // 8) P1 e P6 em lados estritamente opostos da reta P2P3
